INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(94831, 'ruRU', '', 'Сложи обычное массовое производство оружия Железной Орды с осквернением Скверной — и получишь вот этот бардак внизу.$b$bОни строят танки, пушки и пехотное оружие, пропитанное энергией Скверны. А ещё что-то покрупнее дальше внутри — то, что нам действительно стоит помешать им построить.', 24330),
(94833, 'ruRU', '', 'Я толком не разглядел, да мне и не нужно было — там наверху настоящий рай для Пылающего Легиона. Призывают гигантских демонов, с неба сыплются инферналы, культисты поддерживают поток осквернённой воды...$b$bБудь там очень осторожен, всё там большое и злое. Настоятельно советую взять с собой друзей, прежде чем предпринимать там какие-либо наступательные действия.', 24330),
(94893, 'ruRU', '', '[PH] Спасибо, что освободил меня! Я сейчас же убегаю!', 24330),
(94894, 'ruRU', '', 'Заводи нас!', 24330),
(94900, 'ruRU', '', 'Я жажду кровопролития...', 24330),
(94901, 'ruRU', '', 'Гул''дан дарует нам силу!', 24330),
(94902, 'ruRU', '', 'Должен... убить!', 24330),
(94908, 'ruRU', '', 'Гул''дан не должен преуспеть. Пока я жив, мы будем противостоять Легиону.', 24330),
(94917, 'ruRU', '', 'Даже ему не стоит надеяться одолеть Ксавия в одиночку. Нужно немедленно его найти.', 24330),
(94963, 'ruRU', '', 'WARNING: CONTENT BEYOND THIS POINT IS VERY UGLY FIRST PASS. IT''S PLAYABLE, BUT DO SO AT YOUR OWN RISK.', 24330),
(94964, 'ruRU', '', '$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TInterface\\Icons\\achievement_character_bloodelf_female.blp:40|t$B[Леди Лиадрин] Эй, ты. Сюда!', 24330),
(94965, 'ruRU', '', '[NYI - SEE A COOL SCENE WITH RAVENCREST & GUL''DAN TURNING THE ILLIDARI.]', 24330),
(94968, 'ruRU', '', 'Смерть — это только начало!', 24330),
(94969, 'ruRU', '', 'Вы слышали хозяина. Эти незваные гости причинили достаточно хлопот!', 24330),
(94970, 'ruRU', '', 'Наконец... стал единым... с хозяином...', 24330),
(94971, 'ruRU', '', 'Прекратить обстрел!', 24330),
(94972, 'ruRU', '', 'Занять палубные орудия! Всей команде приготовиться к встрече с врагом!', 24330),
(94973, 'ruRU', '', 'Наездники на грифонах, первое крыло, приготовиться к снижению! Второе крыло, держать позицию!', 24330),
(94974, 'ruRU', '', 'Приближаются вражеские летуны! Всем орудиям — огонь по готовности!', 24330),
(94984, 'ruRU', '', 'Абордажная команда на палубе!', 24330),
(94986, 'ruRU', '', 'A quest objective event fires at this point.', 24330),
(94997, 'ruRU', '', 'Даркгроув бежал в ближайшую пещеру. Выследи его и покончи с этим.', 24330),
(95007, 'ruRU', '', '[PLACEHOLDER SCENE] The tears have been stolen and the guards are dead! The player will see Xavius escape with the tears before anything can be done.', 24330),
(95008, 'ruRU', '', 'Битва продолжается, командир. Куда нам направить усилия?', 24330),
(95009, 'ruRU', '', 'Враги окружают нас, командир. Где сегодня прольём их кровь?', 24330),
(95011, 'ruRU', '', 'Сами горы сегодня истекают кровью, командир. Идём, отсрочим конец света ещё на день!', 24330),
(95012, 'ruRU', '', 'Наши разведчики доложили, командир. Нас превосходят числом со всех сторон. Славный денёк для битвы!', 24330),
(95013, 'ruRU', '', 'Так много врагов... так мало времени... Кому сегодня умирать?', 24330),
(95014, 'ruRU', '', 'Джунгли таят в себе множество опасностей. Разумно было бы сегодня перейти в наступление.', 24330),
(95015, 'ruRU', '', 'Если это действительно конец света, то встретим его на полях сражений!', 24330),
(95016, 'ruRU', '', 'Гул''дан нас ещё не сломил, командир. Куда нанесём удар сегодня?', 24330),
(95033, 'ruRU', '', 'Работай быстро. У тебя будет лишь короткое окно времени, чтобы выковать из раскалённых брусков лей-камня нужные тебе детали.', 24330),
(95046, 'ruRU', '', 'Этот храм стоял поколениями как дань Богине Луны, Элуне.$b$bЭто не первый раз, когда Пылающий Легион пытается его уничтожить... и они потерпят неудачу, как и прежде.', 24330),
(95055, 'ruRU', '', 'Теперь он наш! Сосредоточьтесь на их командире!', 24330),
(95058, 'ruRU', '', 'Берегись, инферналы!', 24330),
(95066, 'ruRU', '', 'Ты... должен добраться до храма...', 24330),
(95076, 'ruRU', '', 'Какое опустошение. Нужно уничтожить этих чудовищ.', 24330),
(95077, 'ruRU', '', 'Призови мой гнев, чтобы очистить землю от этих противоестественных тварей.', 24330),
(95078, 'ruRU', '', 'Боюсь, этот лес уже не спасти. Нужно спешить.', 24330),
(95081, 'ruRU', '', 'Меня больше никогда не возьмут в плен. Никогда!', 24330);
